Certainly! Below is an example of a simple C++ program that creates a singly linked list using pointers. The program includes the ability to insert nodes at the end of the list and print the entire list.

```cpp
#include <iostream>

// Define a Node structure
struct Node {
    int data;
    Node* next;

    // Constructor to simplify node creation
    Node(int data) : data(data), next(nullptr) {}
};

// Define a LinkedList class to handle list operations
class LinkedList {
public:
    // Constructor
    LinkedList() : head(nullptr) {}

    // Method to insert a node at the end of the list
    void insert(int value) {
        Node* newNode = new Node(value);
        if (head == nullptr) {
            head = newNode;
        } else {
            Node* temp = head;
            while (temp->next != nullptr) {
                temp = temp->next;
            }
            temp->next = newNode;
        }
    }

    // Method to print all nodes in the list
    void print() {
        Node* temp = head;
        while (temp != nullptr) {
            std::cout << temp->data << " ";
            temp = temp->next;
        }
        std::cout << std::endl;
    }

    // Destructor to clean up all nodes
    ~LinkedList() {
        Node* current = head;
        while (current != nullptr) {
            Node* next = current->next;
            delete current;
            current = next;
        }
        head = nullptr;
    }

private:
    Node* head; // Pointer to the first node in the list
};

int main() {
    LinkedList list;

    // Insert some nodes into the list
    list.insert(10);
    list.insert(20);
    list.insert(30);
    list.insert(40);

    // Print the list
    std::cout << "The linked list contains: ";
    list.print();

    return 0;
}
```

This simple program demonstrates how to create a linked list, insert new nodes at the end, and print the list. Note that the destructor of the `LinkedList` class ensures that all dynamically allocated nodes are properly deleted when the list is destroyed to prevent memory leaks.

