Here is some C++ code that uses pointers for linked lists:

```cpp
#include <iostream>
using namespace std;

// Node structure 
struct Node {
  int data;
  Node* next;
};

// Linked list class
class LinkedList {
private:
  Node* head;

public: 
  LinkedList() {
    head = NULL;
  }

  // Inserts new node at the end
  void insert(int newData) {
    Node* newNode = new Node();
    newNode->data = newData;
    newNode->next = NULL;

    if(head == NULL) {
      head = newNode;
      return;
    }

    Node* current = head;
    while(current->next != NULL) {
      current = current->next;
    }

    current->next = newNode;
  }

  // Prints the linked list
  void printList() {
    Node* current = head;

    while(current != NULL) {
      cout << current->data << " ";
      current = current->next;
    }
  }
};

int main() {
  LinkedList myList;

  myList.insert(5);
  myList.insert(10);
  myList.insert(15);

  myList.printList();

  return 0;
}
```

The key things to note:

- Node struct holds data and a pointer to next node
- Linked list class has pointer to head node 
- insert() traverses to end of list using next pointer and inserts new node
- printList() traverses list using next pointer to print data

So pointers are used to connect nodes and traverse the linked list.

