Certainly! Here's an example of adding JavaScript code within the `<script>` tags to make the calculator functional:

```html
<!DOCTYPE html>
<html lang="en">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>HTML5 Calculator</title>
    <style>
        /* CSS styles here */
    </style>
</head>

<body>
    <div class="calculator">
        <span class="calculator-display">0</span>
        <div class="buttons">
            <button onclick="appendNumber(7)">7</button>
            <button onclick="appendNumber(8)">8</button>
            <button onclick="appendNumber(9)">9</button>
            <button onclick="setOperator('/')">/</button>
        </div>
        <div class="buttons">
            <button onclick="appendNumber(4)">4</button>
            <button onclick="appendNumber(5)">5</button>
            <button onclick="appendNumber(6)">6</button>
            <button onclick="setOperator('*')">×</button>
        </div>
        <div class="buttons">
            <button onclick="appendNumber(1)">1</button>
            <button onclick="appendNumber(2)">2</button>
            <button onclick="appendNumber(3)">3</button>
            <button onclick="setOperator('-')">-</button>
        </div>
        <div class="buttons">
            <button onclick="appendNumber(0)">0</button>
            <button onclick="appendDecimal('.')">.</button>
            <button id="clear" onclick="clearDisplay()">C</button>
            <button onclick="setOperator('+')">+</button>
        </div>
        <div class="operator-row">
            <button id="percent" onclick="calculatePercentage()">%</button>
        </div>
    </div>

    <script>
        const display = document.querySelector('.calculator-display');
        let currentNumber = '0';
        let operator = null;
        let previousNumber = null;

        function updateDisplay() {
            display.textContent = currentNumber;
        }

        function appendNumber(number) {
            if (currentNumber === '0' && number !== '.') {
                currentNumber = '';
            }
            currentNumber += number;
            updateDisplay();
        }

        function appendDecimal(decimal) {
            if (!currentNumber.includes(decimal)) {
                currentNumber += decimal;
                updateDisplay();
            }
        }

        function setOperator(selectedOperator) {
            operator = selectedOperator;
            previousNumber = currentNumber;
            currentNumber = '0';
            updateDisplay();
        }

        function calculatePercentage() {
            currentNumber = parseFloat(currentNumber) / 100;
            updateDisplay();
        }

        function clearDisplay() {
            currentNumber = '0';
            operator = null;
            previousNumber = null;
            updateDisplay();
        }

        function calculate() {
            let result;
            const prev = parseFloat(previousNumber);
            const current = parseFloat(currentNumber);

            if (isNaN(prev) || isNaN(current)) {
                return;
            }

            switch (operator) {
                case '+':
                    result = prev + current;
                    break;
                case '-':
                    result = prev - current;
                    break;
                case '*':
                    result = prev * current;
                    break;
                case '/':
                    result = prev / current;
                    break;
                default:
                    return;
            }

            currentNumber = result.toString();
            operator = null;
            previousNumber = null;
            updateDisplay();
        }

        // Attach event listener to the "=" button
        document.querySelector('.buttons').addEventListener('click', function (event) {
            if (event.target.tagName === 'BUTTON' && event.target.textContent === '=') {
                calculate();
            }
        });
    </script>
</body>

</html>
```

In this code, JavaScript functions are added within the `<script>` tags to handle button clicks and perform calculations. The display is updated dynamically using the `updateDisplay()` function. The `appendNumber()`, `appendDecimal()`, `setOperator()`, `calculatePercentage()`, and `clearDisplay()` functions handle different button actions. The `calculate()` function performs the actual calculation based on the selected operator.

Additionally, an event listener is attached to the `buttons` container to listen for clicks on the `=` button and trigger the `calculate()` function.

You can copy and paste this code into an HTML file, save it, and open it in a web browser to see the functional calculator.

