```cpp
#include <SFML/Graphics.hpp>

int main()
{
    sf::RenderWindow window(sf::VideoMode(200, 200), "Smiling Face");

    sf::CircleShape face(100);
    face.setFillColor(sf::Color::Yellow);
    face.setOutlineThickness(10);
    face.setOutlineColor(sf::Color::Black);
    face.setPosition(50, 50);

    sf::CircleShape leftEye(20);
    leftEye.setFillColor(sf::Color::White);
    leftEye.setPosition(80, 70);

    sf::CircleShape rightEye(20);
    rightEye.setFillColor(sf::Color::White);
    rightEye.setPosition(140, 70);

    sf::ConvexShape mouth;
    mouth.setPointCount(4);
    mouth.setPoint(0, sf::Vector2f(100, 130));
    mouth.setPoint(1, sf::Vector2f(120, 150));
    mouth.setPoint(2, sf::Vector2f(140, 150));
    mouth.setPoint(3, sf::Vector2f(160, 130));
    mouth.setFillColor(sf::Color::White);
    mouth.setOutlineThickness(5);
    mouth.setOutlineColor(sf::Color::Black);

    while (window.isOpen())
    {
        sf::Event event;
        while (window.pollEvent(event))
        {
            if (event.type == sf::Event::Closed)
                window.close();
        }

        window.clear();
        window.draw(face);
        window.draw(leftEye);
        window.draw(rightEye);
        window.draw(mouth);
        window.display();
    }

    return 0;
