Certainly! Here's a simple Python code that can calculate expressions entered by the user using the Reverse Polish Notation (RPN) method.

```python
def is_operator(token):
    return token in ['+', '-', '*', '/']

def calculate(expression):
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        elif is_operator(token):
            operand2 = stack.pop()
            operand1 = stack.pop()
            if token == '+':
                stack.append(operand1 + operand2)
            elif token == '-':
                stack.append(operand1 - operand2)
            elif token == '*':
                stack.append(operand1 * operand2)
            elif token == '/':
                stack.append(operand1 / operand2)
        else:
            print("Invalid token:", token)
            return None

    if len(stack) == 1:
        return stack[0]
    else:
        print("Invalid expression")
        return None

expression = input("Enter the expression in RPN format (e.g. '3 4 + 2 *'): ")
result = calculate(expression)
if result is not None:
    print("Result:", result)
```

