Hello! Thank you for your question. I'm going to create a simple C++ program that demonstrates creating two threads, each waiting on a condition variable, and then having the main thread wake them up after a delay.

Here's the code:

```cpp
#include <iostream>
#include <thread>
#include <condition_variable>
#include <mutex>
#include <chrono>

using namespace std;

bool shouldContinue = false;
mutex m;
condition_variable cv;

void waiterFunction(const string& threadName) {
    unique_lock<mutex> lock(m);
    cv.wait(lock, []{ return shouldContinue; });
    cout << "Thread " << threadName << " woke up." << endl;
}

int main() {
    thread thread1(waiterFunction, "Thread 1");
    thread thread2(waiterFunction, "Thread 2");

    // Wait for one second before notifying the threads
    this_thread::sleep_for(chrono::seconds(1));

    // Notify the threads to wake them up
    {
        unique_lock<mutex> lock(m);
        shouldContinue = true;
        cv.notify_all();
    }

    // Wait for both threads to finish
    thread1.join();
    thread2.join();

    return 0;
}
```

