```objective-c
id value = userInfo[MTLCommandBufferEncoderInfoErrorKey];
if ([value isKindOfClass:[MTLCommandBufferEncoderInfo class]]) {
    MTLCommandBufferEncoderInfo *encoderInfo = (MTLCommandBufferEncoderInfo *)value;
