Here is an example of a basic patients management system in JavaScript:

```js
// Patient class
class Patient {
  constructor(id, name, age) {
    this.id = id;
    this.name = name;
    this.age = age;
  }
}

// Patients database
let patients = [];

// Add patient
function addPatient(id, name, age) {
  const patient = new Patient(id, name, age);
  patients.push(patient);
}

// Get patient by id
function getPatient(id) {
  return patients.find(p => p.id === id); 
}

// Delete patient
function deletePatient(id) {
  patients = patients.filter(p => p.id !== id);
}

// List all patients
function listPatients() {
  patients.forEach(p => {
    console.log(`${p.id} - ${p.name} - ${p.age}`); 
  });
}

// Usage
addPatient(1, "John", 30);
addPatient(2, "Mary", 25);

let patient = getPatient(1); 
console.log(patient.name); // Outputs "John"

deletePatient(2);

listPatients(); 
// Outputs:
// 1 - John - 30
```

The key things it allows you to do:

- Add new patients 
- Get a patient by id
- Delete patients
- List all patients

Additional features could include updating patients, searching by name, filtering by age etc. And storing the data in a database rather than just an in-memory array.

