SEC("kprobe/sys_accept")
int kprobe_accept(struct pt_regs *ctx)
{
    struct data_t data = {};
    __u64 pid = bpf_get_current_pid_tgid();
    __u32 saddr, daddr;
    __u16 sport, dport;
    __u64 fd = PT_REGS_RC(ctx);
    struct sock_key key = {};
    struct sock_val *pval;

    struct sockaddr_in sa;
    bpf_probe_read(&sa, sizeof(sa), (void*)PT_REGS_PARM2(ctx));
    saddr = sa.sin_addr.s_addr;
    sport = sa.sin_port;
    bpf_probe_read(&sa, sizeof(sa), (void*)PT_REGS_PARM1(ctx));
    daddr = sa.sin_addr.s_addr;
    dport = sa.sin_port;

    key.saddr = saddr;
    key.daddr = daddr;
    key.sport = sport;
    key.dport = dport;

    pval = bpf_map_lookup_elem(&sock_map, &key);
    if (!pval) {
        struct sock_val val = {};
        val.pid = pid;
        val.fd = fd;
        bpf_map_update_elem(&sock_map, &key, &val, BPF_ANY);
    } else {
        pval->pid = pid;
        pval->fd = fd;
    }

    data.pid = pid;
    data.saddr = saddr;
    data.daddr = daddr;
    data.sport = sport;
    data.dport = dport;
    data.fd = fd;
    bpf_ringbuf_output(&ringbuf, &data, sizeof(data), 0);
    return 0;
}

