Here is a function to convert an integer to a string in C# without using the built-in ToString():

```c#
using System;

public class IntegerToString
{
    public static string Convert(int number)
    {
        // Check if the number is negative
        bool isNegative = number < 0;

        // Convert the number to its absolute value
        int absNumber = Math.Abs(number);

        // Create a string to store the result
        string result = "";

        // Iterate through the digits of the number
        while (absNumber > 0)
        {
            // Get the last digit of the number
            int lastDigit = absNumber % 10;

            // Convert the last digit to a character
            char digitCharacter = (char)('0' + lastDigit);

            // Add the character to the result string
            result = digitCharacter + result;

            // Remove the last digit from the number
            absNumber /= 10;
        }

        // If the number was negative, add a minus sign to the result
        if (isNegative)
        {
            result = "-" + result;
        }

        // Return the result string
        return result;
    }
}
```

Here is an example of how to use the function:

```c#
using System;

public class Program
{
    public static void Main()
    {
        // Convert an integer to a string
        string result = IntegerToString.Convert(123);

        // Print the result
        Console.WriteLine(result); // Output: 123
    }
}
```

