	import type { Writable } from 'svelte/store';
	import { blur, fade } from 'svelte/transition';
	import type { EventBuilderStore } from './types';

	import { browser } from '$app/environment';
	import AmbientLoading from '$lib/components/AmbientLoading/AmbientLoading.svelte';
	import { EventBuilderSchema } from '$lib/validation/validatorObjects';
	import type { typeToFlattenedError, z } from 'zod';
	import BuilderEventForm from './BuilderEventForm.svelte';
	import BuilderFormNavigation from './BuilderFormNavigation.svelte';
	import BuilderSidebar from './BuilderSidebar.svelte';

	const EMPTY_EVENT = {
		eventName: '',
		companyUrl: '',
		companyName: '',
		eventType: '',
		eventDescription: '',
		eventGoals: '',
		eventLocation: '',
		eventStartTime: '',
		eventEndTime: '',
		eventTimezone: '',
		voiceStyle: 'Salesperson',
		emailChain: false,
		inMail: false,
		eventUrl: ''
	};
	const eventBuilderStore: Writable<EventBuilderStore> = localStorageStore('eventBuilderStore', {
		...EMPTY_EVENT
	});

	let selectedStep = 'overview';
	let hasAttemptedSubmit = false;

	let eventId = '';

	$: {
		if ($page.route.id) {
			selectedStep = $page.route.id.split('/builder/').at(1)?.split('/').at(0) || 'overview';
		}
	}

	function updateFormValues(key: string, value: string) {
		$eventBuilderStore = {
			...$eventBuilderStore,
			[key]: value
		};
	}

	function handleInput(
		event: Event & {
			currentTarget: EventTarget & HTMLInputElement;
		}
	) {
		const { name, value } = event.detail.target;
		updateFormValues(name, value);
	}

	function clearField(fieldName: keyof EventBuilderStore) {
		delete $eventBuilderStore[fieldName];
		$eventBuilderStore = $eventBuilderStore;
	}

	function clearAllFields() {
		$eventBuilderStore = { ...EMPTY_EVENT };
	}

	const handleSkipCallback: Writable<(() => void) | null> = writable(null);
	const handleNextCallback: Writable<(() => void) | null> = writable(null);
	const handleForwardsArrowCallback: Writable<(() => void) | null> = writable(null);
	const handleBackwardsArrowCallback: Writable<(() => void) | null> = writable(null);

	const stepTitle = writable('Create a new event');
	const stepCount = writable('0');
	const isSkipAvailable = writable(false);
	const isLoading = writable(false);
	const nextButtonLabel = writable('Next');

	const errors = writable<typeToFlattenedError<z.infer<typeof EventBuilderSchema>>>();

	setContext('formHandler', {
		eventBuilderStore,
		handleInput,
		updateFormValues,
		clearField,
		clearAllFields,
		handleSkipCallback,
		handleNextCallback,
		handleForwardsArrowCallback,
		handleBackwardsArrowCallback,
		stepTitle,
		stepCount,
		isSkipAvailable,
		isLoading,
		nextButtonLabel,
		errors
	});

	const handleBuilderStepButtonClick = (stepName: string) => {
		if (!hasAttemptedSubmit) {
			$errors = undefined;
		}
		if (!$page.route.id?.includes(stepName)) {
			selectedStep = stepName;
			goto(`/events/builder/${stepName}`);
		}
	};

	function handleSkip() {
		if (!hasAttemptedSubmit) {
			$errors = undefined;
		}
		$handleSkipCallback?.();
	}

	function handleNext() {
		const validatedForm = EventBuilderSchema.safeParse($eventBuilderStore);
		if (!validatedForm.success) {
			$errors = validatedForm.error.flatten();
		} else if (!hasAttemptedSubmit) {
			console.log('this should get hit now!');
			$errors = undefined;
		}
		$handleNextCallback?.();
	}

	function handleBackwardsArrow() {
		$handleBackwardsArrowCallback?.();
	}

	function handleForwardsArrow() {
		$handleForwardsArrowCallback?.();
	}

	$: {
		if (browser) {
			localStorage.setItem('localStoarge', 'test working');
			eventId = $eventBuilderStore.eventId;
		}
	}

	const enhanceNewEventCreation = (({ cancel, formData }) => {
		if ($page.route.id !== '/events/builder/preferences') {
			handleNext();
			cancel();
			return;
		}
		const validatedForm = EventBuilderSchema.safeParse(Object.fromEntries(formData));
		if (!validatedForm.success) {
			$errors = validatedForm.error.flatten();
			hasAttemptedSubmit = true;
			cancel();
			return;
		}

		for (const [key, value] of Object.entries(Object.fromEntries(formData))) {
			if (key === 'eventUrl' && (!value || (value as string).length === 0)) {
				formData.delete('eventUrl');
			}
			if (key === 'companyUrl' && (!value || (value as string).length === 0)) {
				formData.delete('companyUrl');
			}
		}

		return async ({ result }) => {
			await applyAction(result);
		};
	}) satisfies SubmitFunction;
</script>

{#if $isLoading}
	<AmbientLoading />
{/if}

<div class="flex flex-row gap-2 min-h-192">
	<BuilderSidebar {selectedStep} {handleBuilderStepButtonClick} {hasAttemptedSubmit} />

	<div class="flex-1 flex flex-col variant-filled-surface p-5 ring-transparent">
		<div class="grow">
			<div class="flex flex-col h-full">
				<section class="flex flex-row justify-between">
					<h5 class="h5" transition:fade>{$stepTitle}</h5>
					<span transition:blur>{$stepCount}</span>
				</section>
				<div class="flex flex-1 pb-14 pt-4">
					<slot />
				</div>
			</div>
		</div>
		<BuilderFormNavigation
			{handleBackwardsArrow}
			{handleForwardsArrow}
			isSkipAvailable={$isSkipAvailable}
			{handleSkip}
		>
			<BuilderEventForm {eventId} {enhanceNewEventCreation} nextButtonLabel={$nextButtonLabel} />
		</BuilderFormNavigation>
	</div>
</div>


