```cpp
#include <Wire.h>
#include <Adafruit_L3G4200D.h>
#include <Adafruit_ADXL345.h>
#include <Adafruit_MC5883L.h>
#include <Adafruit_BMP085.h>
#include <WiFiEsp32.h>

#define WIFI_SSID "your_ssid"
#define WIFI_PASSWORD "your_password"
#define I2C_ADDRESS_L3G 0x68
#define I2C_ADDRESS_ADXL 0x53
#define I2C_ADDRESS_MAG 0x0C
#define I2C_ADDRESS_BMP 0x76

Adafruit_L3G4200D l3g;
Adafruit_ADXL345 adxl;
Adafruit_MC5883L mag;
Adafruit_BMP085 bmp;

WiFiEsp32 wifi;
String serialData[10];

void setup() {
  Serial.begin(115200);
  wifi.begin(WIFI_SSID, WIFI_PASSWORD);
  if (!wifi.isconnected()) {
    Serial.println("WiFi connection failed");
    while (1);
  }
  l3g.begin(I2C_ADDRESS_L3G);
  adxl.begin(I2C_ADDRESS_ADXL);
  mag.begin(I2C_ADDRESS_MAG);
  bmp.begin(I2C_ADDRESS_BMP);
}

void loop() {
  // Read sensor data
  float l3g_x, l3g_y, l3g_z, adxl_x, adxl_y, adxl_z, mag_x, mag_y, mag_z, temp, pressure;
  l3g.getGyro(&l3g_x, &l3g_y, &l3g_z);
  adxl.getAccel(&adxl_x, &adxl_y, &adxl_z);
  mag.getMag(&mag_x, &mag_y, &mag_z);
  bmp.getPressure(&pressure, &temp);

  // Calibrate by subtracting average offset (if needed)
  // For simplicity, we'll assume an average offset of 0 for each axis
  l3g_x -= 0;
  l3g_y -= 0;
  l3g_z -= 0;
  adxl_x -= 0;
  adxl_y -= 0;
  adxl_z -= 0;
  mag_x -= 0;
  mag_y -= 0;
  mag_z -= 0;

  // Append sensor values to serial array
  serialData[0] = "Heading: " + String(l3g.getHeading(), 2) + "° ";
  serialData[1] = "Altitude: " + String(pressure, 4) + " hPa ";
  serialData[2] = "X: " + String(adxl_x, 4) + " g ";
  serialData[3] = "Y: " + String(adxl_y, 4) + " g ";
  serialData[4] = "Z: " + String(adxl_z, 4) + " g ";
  serialData[5] = "Mag X: " + String(mag_x, 4) + " μT ";
  serialData[6] = "Mag Y: " + String(mag_y, 4) + " μT ";
  serialData[7] = "Mag Z: " + String(mag_z, 4) + " μT ";
  serialData[8] = "Temp: " + String(temp, 3) + " °C ";
  serialData[9] = "Time: " + String(wifi.localTime(), 16);

  // Send data over serial
  for (int i = 0; i < 10; i++) {
    Serial.print(serialData[i]);
    if (i < 9) {
      Serial.print(" ");
    }
  }
  Serial.println();

  // Append timestamp with WiFi IP
  String timestamp = "Time: " + wifi.localIP() + " ";
  serialData[0] = timestamp;
  Serial.println(serialData[0]);

  // Wait for a second before sending next iteration
  delay(1000);
}

// WiFi data append function to save the timestamp
void appendTimestamp(String &data) {
  DateTime now = datetime();
  String timestamp = now.toString("yyyy-MM-dd HH:mm:ss.SSS");
  data += " " + timestamp;
}
```
This code uses the Adafruit Unified Sensor library for theL3G4200D gyroscope, ADXL345 accelerometer, MC5883L magnetometer, and BMP085 barometer. It connects to WiFi, reads the sensor data, and appends the timestamp with the WiFi IP address for accurate time. The sensor values are printed out to the serial monitor as a space-separated array.

