    // Create the outer cylinder
    cylinder(h = n, r1 = m/2, r2 = m/2-w);

    // Create the inner cylinder
    cylinder(h = n, r1 = 0, r2 = m/2-2*w);

    // Create the screw holes
    for (i = [0:k-1]) {
        translate([m/2*cos(2*pi*i/k), m/2*sin(2*pi*i/k), n]) {
