#!/usr/bin/env python3

import requests
from bs4 import BeautifulSoup
from urllib.parse import quote

def extract_geekbench_data(html):
	soup = BeautifulSoup(html, 'html.parser')
	systems = soup.find_all('div', class_='list-col-inner')
	extracted_data = []

	for system in systems:
		system_name_tag = system.find('a')
		system_name = system_name_tag.get_text(strip=True) if system_name_tag else "Unknown"

		cpu_name_tag = system.find('span', class_='list-col-model')
		cpu_name = cpu_name_tag.get_text(strip=True) if cpu_name_tag else "Unknown CPU"

		scores = system.find_all('span', class_='list-col-text-score')
		if len(scores) >= 2:
			single_core_score = scores[0].get_text(strip=True)
			multi_core_score = scores[1].get_text(strip=True)
			extracted_data.append({
				'System Name': system_name, 
				'CPU Name': cpu_name,
				'Single-Core Score': single_core_score, 
				'Multi-Core Score': multi_core_score
			})

	return extracted_data

def count_search_pages(html):
	soup = BeautifulSoup(html, 'html.parser')
	pagination_container = soup.find('ul', class_='pagination')
	if pagination_container:
		# Extracting all the page items
		page_items = pagination_container.find_all('li', class_='page-item')
		# Finding the last page number from the page item list
		last_page_item = page_items[-2] if len(page_items) > 2 else None
		last_page_number = int(last_page_item.find('a').text) if last_page_item else 0
		return last_page_number
	else:
		return 0

def fetch_and_extract_geekbench_data(query):
	encoded_query = quote(query)
	url = f'https://browser.geekbench.com/search?page=1&q={encoded_query}&utf8=%E2%9C%93'

	try:
		response = requests.get(url)
		if response.status_code != 200:
			return "Failed to retrieve data from Geekbench.", 0

		extracted_data = extract_geekbench_data(response.content)
		number_of_pages = count_search_pages(response.content)
		return extracted_data, number_of_pages

	except Exception as e:
		return f"An error occurred: {str(e)}", 0

