Here's a simple implementation of a feedforward neural network with gradient descent in Python. This example assumes you're working with a binary classification problem, so the output layer has one neuron with a sigmoid activation function. You can extend this implementation to multi-class classification or other use cases by modifying the output layer and activation functions.
```python
import numpy as np

class Neuron:
    def __init__(self, input_decay, output_location, output_function):
        self.input_decay = input_decay
        self.output_location = output_location
        self.output_function = output_function
        self.threshold_upper = 0.5
        self.threshold_lower = -0.5

class NeuralNetwork:
    def __init__(self, layers):
        self.layers = layers
        self.neuron_count = len(layers)

    def forward(self, input_data, initial_output=None):
        for layer in self.layers:
            if initial_output is None:
                output = input_data
            else:
                output = initial_output

            for neuron in layer:
                input_data = np.reshape(output, (-1, 1))
                activation = neuron.output_function(np.dot(input_data, neuron.input_decay))

                if neuron.threshold_lower < activation < neuron.threshold_upper:
                    activation = 1
                else:
                    activation = 0

                output = np.vstack((output, activation))
        return output

    def train(self, input_data, target):
        output_data = self.forward(input_data)
        mse = np.mean((output_data - target) ** 2)
        learning_rate = 0.01

        for layer in self.layers:
            for neuron in layer:
                gradient = (output_data - target) * neuron.output_function(np.dot(input_data, neuron.input_decay))
                neuron.input_decay -= learning_rate * gradient

        return mse

