def sigmoid(x):
    return 1 / (1 + np.exp(-x))

def build_ann(input_dim, hidden_neurons, output_neurons):
    input_layer = [Neuron(np.ones(input_dim), np.zeros(hidden_neurons), sigmoid)]
    hidden_layer = []
    for _ in range(hidden_neurons):
        hidden_layer.append([Neuron(np.zeros(input_dim), np.zeros(output_neurons), sigmoid)])
    output_layer = [Neuron(np.zeros(hidden_neurons[0]), output_neurons, sigmoid)]

    return NeuralNetwork(input_layer + hidden_layer + output_layer)

# Example usage
