				rb.MovePosition(rb.position + transform.forward * Time.deltaTime * followSpeed);
			}
		}

		public void Ai_Jump(){
			if(IsGrounded() && !_IsJumping){
				rb.AddForce((Vector3.up * jumpForce) + (transform.forward * (jumpForce/2)), ForceMode.VelocityChange);
				_IsJumping = true;
			}
		}

		public void Ai_LongJump(){
			if(IsGrounded() && !_IsJumping){
