```
private void Ai_Avoidance(LayerMask Layer)
{
    if (_HasAvoidance)
    {
        Collider[] hitColliders = Physics.OverlapSphere(transform.position, collisionRadius, Layer);

        foreach (Collider hitCollider in hitColliders)
        {
            // Calculate the direction of the hitCollider from the AI's position
            Vector3 direction = (hitCollider.transform.position - transform.position).normalized;

            // Apply avoidance force in the opposite direction
            rb.AddForce(-direction * avoidSpeed, ForceMode.Impulse);

            // Set the avoidance flag to true
            _IsAvoiding = true;
        }

        // If the AI is avoiding an obstacle, set its velocity to zero to prevent sliding
        if (_IsAvoiding)
        {
