Here is some sample NestJS code to implement basic user authentication:

1. Create a User entity:

```typescript
@Entity()
export class User {

  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  username: string;

  @Column()
  password: string;

}
```

2. Create a AuthService:

```typescript
@Injectable()
export class AuthService {

  constructor(
    @InjectRepository(User)
    private usersRepository: Repository<User>
  ) {}

  async validateUser(username: string, pass: string): Promise<any> {
    const user = await this.usersRepository.findOne({ username });
    if (user && user.password === pass) {
      return user;
    }
    return null;
  }

}
``` 

3. Create AuthGuard:

```typescript
@Injectable()
export class AuthGuard implements CanActivate {

  constructor(private authService: AuthService) {}

  canActivate(
    context: ExecutionContext
  ): boolean | Promise<boolean> {

    const request = context.switchToHttp().getRequest();
    const user = this.authService.validateUser(
      request.body.username, 
      request.body.password
    );

    if (user) {
      request.user = user;
      return true;
    }

    return false;
  }

}
```

4. Protect routes with AuthGuard:

```typescript
@UseGuards(AuthGuard)
@Controller('protected')
export class ProtectedController {

  @Get()
  getProtected() {
    return 'Protected route!'; 
  }

}
```

This provides a basic authentication flow. You can enhance it further with JWT tokens, refresh tokens, etc.

