Here's a simple `` qgc `` file that creates a square mission pattern with sides 5m and height 10m, and flies at 1m/s:

```javascript
#include <qgc.h>

struct Mission {
    int m;
    int h;
};

struct Drone {
    int speed;
};

struct MissionPattern {
    Mission m;
    Drone d;
};

MissionPattern createMissionPattern(Mission m, Drone d) {
    MissionPattern pattern = {m, d};
    pattern.m.h /= 2;
    pattern.m.h *= 2;
    return pattern;
}

MissionPattern flyWithSpeed(MissionPattern pattern, Drone d) {
    pattern.d.speed = d.speed * 2;
    pattern.m.h *= 2;
    return pattern;
}

int main() {
    Mission m = {5, 10};
    Drone d = {1, 0};
    MissionPattern pattern = createMissionPattern(m, d);
    MissionPattern flyingPattern = flyWithSpeed(pattern, d);
    qgc_drawMissionPattern(flyingPattern, 1);
    qgc_show();
    return 0;
}
```

