    {
        memoryStream = new MemoryStream();
        binaryWriter = new BinaryWriter(memoryStream);
        binaryReader = new BinaryReader(memoryStream);
    }

    public void Serialize(ISerialize obj)
    {
        obj.Serialize(this);
    }

    public void SwitchMode(Mode mode)
    {
        CurrentMode = mode;
        memoryStream.Position = 0;
    }

    public void WriteInt32(int value)
    {
        binaryWriter.Write(value);
    }

    public int ReadInt32()
    {
        return binaryReader.ReadInt32();
    }

    // Add other read and write methods for different types as needed

    public byte[] ToArray()
    {
        return memoryStream.ToArray();
    }

    public void Dispose()
    {
        binaryWriter?.Dispose();
        binaryReader?.Dispose();
        memoryStream?.Dispose();
    }
}

// Example of a class implementing ISerialize
public class MySerializableClass : ISerialize
{
    public int MyIntProperty { get; set; }

    public void Serialize(BinarySerializer serializer)
    {
        if (serializer.CurrentMode == BinarySerializer.Mode.Write)
        {
            serializer.WriteInt32(MyIntProperty);
        }
        else if (serializer.CurrentMode == BinarySerializer.Mode.Read)
        {
            MyIntProperty = serializer.ReadInt32();
        }
    }
}

// Example usage
class Program
{
    static void Main()
    {
        var myObject = new MySerializableClass { MyIntProperty = 123 };

        using (var serializer = new BinarySerializer())
        {
            // Serialize the object
            serializer.SwitchMode(BinarySerializer.Mode.Write);
            serializer.Serialize(myObject);

            // Get the binary data
            byte[] data = serializer.ToArray();

            // Deserialize the object from the binary data
            var deserializedObject = new MySerializableClass();
            using (var deserializer = new BinarySerializer())
            {
                deserializer.SwitchMode(BinarySerializer.Mode.Read);
                deserializer.memoryStream.Write(data, 0, data.Length);
                deserializer.memoryStream.Position = 0; // Reset stream position to start
                deserializer.Serialize(deserializedObject);
            }

            Console.WriteLine(deserializedObject.MyIntProperty); // Outputs 123
        }
    }
}
```

This is a basic example and can be expanded to include more type-specific read and write methods, and handle more complex scenarios like nested objects, collections, and error handling. Remember to dispose of the `BinarySerializer` after using it to free up resources. You can also implement the `IDisposable` interface to ensure proper cleanup.

