  output reg [7:0] rd_data,
  output empty,
  output full
);

  parameter ID = 15;
  parameter DEP = 4;

  reg [ID-1:0] memory [0:DEP-1];
  reg [7:0] wr_ptr, rd_ptr;
  wire count = (wr_ptr >= rd_ptr) ? (wr_ptr - rd_ptr) : (DEP - wr_ptr - rd_ptr);

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      rd_data <= 8'b0;
      rd_ptr <= 0;
      count <= 0;
    end else if (rd_en && !empty) begin
      count <= count - 1;
      rd_data <= memory[rd_ptr];
      rd_ptr <= rd_ptr + 1;
    end else if (wr_en && !full) begin
      count <= count + 1;
      wr_data <= memory[wr_ptr];
      wr_ptr <= wr_ptr + 1;
    end
  end

  assign empty = (wr_ptr >= rd_ptr);
  assign full = (count == DEP);

endmodule
```
This program generates a simple FIFO with a queue size of 16 and a data transfer rate of one item per cycle. It has a reset input, an enable write input, and inputs for the write data and read data. The program uses a 16-bit buffer to store the data, and a counter to keep track of the current position in the buffer. It also has outputs for the empty and full signals, which are determined by whether the buffer is full or not.

