Here is a skeleton for the Trait class:
```
export class Trait {
  private average: number;
  private stdev: number;
  private value: number;
  private costFunction: (value: number) => number;

  constructor(average: number, stdev: number) {
    this.average = average;
    this.stdev = stdev;
    this.value = average;
    this.costFunction = this.calculateCost;
  }

  private calculateCost(value: number) {
    // Calculate cost based on how far the value is from the average
    // The cost should increase exponentially the further from the average
    // Example implementation:
    const distanceFromAverage = Math.abs(value - this.average);
    const cost = Math.pow(2, distanceFromAverage / this.stdev);
    return cost;
  }

  increase(amount: number, budget: number): boolean {
    const newValue = this.value + amount;
    const cost = this.costFunction(newValue);
    if (cost <= budget) {
      this.value = newValue;
      return true;
    } else {
      return false;
    }
  }

  decrease(amount: number, budget: number): boolean {
    const newValue = this.value - amount;
    const cost = this.costFunction(newValue);
    if (cost <= budget) {
      this.value = newValue;
      return true;
    } else {
      return false;
    }
  }

  get value() {
    return this.value;
  }

  get average() {
    return this.average;
  }

  get stdev() {
    return this.stdev;
  }
}
```
It is important to note that this is just a skeleton, and the `calculateCost` function may need to be adjusted based on the specific requirements of your game. Also, you can add additional methods or properties to the class as needed.

